# Glossary source. Run: python3 glossary_src.py -> glossary.json
# Fields: t term, f full form, d definition (1-2 sentences), m module that teaches it,
# only = tag only in these modules (ambiguous abbreviations), note = other meanings.
G = [
# --- signals, transforms ---
("SNR","signal-to-noise ratio","Ratio of signal power to noise power, usually in dB. Sets detectability and the precision of every estimate in the course.",10),
("RF","radio frequency (RF data)","The raw, real-valued echo signal around the transducer centre frequency, sampled above its Nyquist rate (typically 4× the centre frequency or more), before demodulation to IQ.",8),
("IQ","in-phase/quadrature (complex baseband)","Complex signal obtained by mixing RF down to baseband and low-pass filtering; I is the real part, Q the imaginary part.",8),
("FFT","fast Fourier transform","An O(N log N) algorithm that computes the DFT.",2),
("IFFT","inverse fast Fourier transform","The fast algorithm for the inverse DFT.",24),
("DFT","discrete Fourier transform","Maps N samples to N complex frequency coefficients; the finite, sampled version of the Fourier transform.",2),
("DTFT","discrete-time Fourier transform","Fourier transform of an infinite discrete-time sequence; a continuous, 2π-periodic function of frequency. The DFT samples it.",2),
("STFT","short-time Fourier transform","Fourier transforms of short, windowed, usually overlapping segments, giving a time–frequency picture.",25),
("LTI","linear time-invariant","A system whose response to a weighted sum of inputs is the same weighted sum of the responses, and whose behaviour does not change over time; fully described by its impulse response.",3),
("FIR","finite impulse response","A digital filter whose impulse response has finite length; always stable and can have exactly linear phase.",9),
("IIR","infinite impulse response","A recursive digital filter whose impulse response never ends; cheaper than FIR for sharp responses but can be unstable and has nonlinear phase.",9),
("LPF","low-pass filter","Passes frequencies below a cut-off and attenuates those above.",8),
("BIBO","bounded-input bounded-output","Stability criterion: every bounded input gives a bounded output. For LTI systems, the impulse response must be absolutely summable.",3),
("PSD","power spectral density","Distribution of a random signal's power over frequency; the Fourier transform of its autocorrelation.",7),
("ENBW","equivalent noise bandwidth","Width of an ideal rectangular filter passing the same white-noise power as a given window or filter.",2),
("DC","direct current (zero frequency)","The zero-frequency (mean) component of a signal.",2),
("WSS","wide-sense stationary","A random process whose mean is constant and whose covariance depends only on the time difference.",7),
("CIC","cascaded integrator–comb","A multiplier-free filter structure used for large decimation factors.",9),
("AR","autoregressive (model)","Model in which each sample is a weighted sum of past samples plus white noise; used for spectral estimation and prediction.",27),
("DPSS","discrete prolate spheroidal sequences","Slepian tapers that maximize energy concentration in a band; the windows of the multitaper method.",27),
("AAF","anti-aliasing filter","Analog low-pass filter before the ADC that removes content above half the sampling rate.",3),
("PRF","pulse repetition frequency","Number of transmit events per second; sets the Doppler Nyquist limit and the maximum imaging depth.",29),
("PRI","pulse repetition interval","Time between transmit events; 1/PRF.",10),
("FBW","fractional bandwidth","Bandwidth divided by centre frequency, often at −6 dB.",4),
("BW","bandwidth","Width of the frequency band a signal or system occupies, usually defined at −3 or −6 dB.",4),
("LFM","linear frequency modulation (chirp)","A pulse whose instantaneous frequency sweeps linearly in time; compressed by a matched filter.",10),
("TB","time–bandwidth product","Code duration times bandwidth; approximately the compression ratio, and the SNR gain of pulse compression relative to a short pulse of equal peak amplitude.",10,[10]),
("PSL","peak sidelobe level","Highest sidelobe relative to the main lobe, in dB, for a beam pattern or a compressed pulse.",10),
("ISLR","integrated sidelobe ratio","Energy in all sidelobes relative to the main-lobe energy, in dB.",23),
("AM","amplitude modulation","Contrast or harmonic pulse sequence that combines transmits of different amplitudes so linear echoes cancel.",15,[15,28]),
("PI","pulse inversion","Two transmits of opposite polarity are summed so linear echoes cancel and even harmonics remain.",15,[15,28]),
("CPS","contrast pulse sequence","Multi-pulse sequence combining amplitude and phase changes to isolate nonlinear microbubble echoes.",28),
# --- linear algebra, estimation, optimization ---
("SVD","singular value decomposition","Factorization A = UΣVᴴ into orthonormal bases and non-negative singular values; the tool behind clutter filtering, conditioning and regularization.",6),
("TSVD","truncated SVD","Regularization that keeps only the largest singular values when inverting.",6),
("PCA","principal component analysis","Finding the directions of largest variance; the SVD of centred data.",6),
("QR","QR decomposition","Factorization into an orthonormal Q and an upper-triangular R; a stable way to solve least squares.",5),
("LS","least squares","Choosing parameters that minimize the sum of squared residuals.",5),
("CRLB","Cramér–Rao lower bound","Lower bound on the variance of any unbiased estimator, given by the inverse Fisher information.",12),
("MLE","maximum-likelihood estimator","The parameter value that makes the observed data most probable.",12),
("MAP","maximum a posteriori","Estimate that maximizes the posterior: likelihood times prior.",12),
("MSE","mean squared error","Average squared estimation error; variance plus squared bias.",12),
("RMSE","root-mean-square error","Square root of the MSE, in the units of the quantity.",12),
("MMSE","minimum mean squared error","Estimator that minimizes the expected squared error; the posterior mean.",12),
("ENR","energy-to-noise ratio","Signal energy divided by noise power spectral density; sets the CRLB for delay and localization.",12),
("NCC","normalized cross-correlation","Cross-correlation of mean-removed signals divided by the square root of the product of their energies, so it lies between −1 and 1; the standard similarity measure for speckle tracking.",11),
("TV","total variation","Regularizer equal to the sum of gradient magnitudes; it favours piecewise-constant images with sharp edges.",13),
("GCV","generalized cross-validation","Rule for choosing a regularization parameter by predicting held-out error without re-fitting.",13),
("ISTA","iterative shrinkage-thresholding algorithm","Proximal-gradient method for L1-regularized problems: a gradient step, then soft thresholding.",13),
("FISTA","fast ISTA","ISTA with Nesterov momentum; the objective error falls as O(1/k²) instead of ISTA's O(1/k) (Beck & Teboulle 2009).",13),
("CGLS","conjugate gradient for least squares","Krylov method that solves least squares without forming AᴴA; stopping early acts as regularization.",13),
("ADMM","alternating direction method of multipliers","Splits an optimization into simpler sub-problems that are solved in turn and tied together by dual variables.",13),
("IRLS","iteratively reweighted least squares","Solves non-quadratic fitting problems as a sequence of weighted least-squares problems.",9),
("GD","gradient descent","Iterative minimization by stepping against the gradient.",14),
("LM","Levenberg–Marquardt","Damped Gauss–Newton method that moves between Gauss–Newton and gradient descent.",14),
("SGD","stochastic gradient descent","Gradient descent using noisy gradients from random subsets of the data.",14),
("FWI","full-waveform inversion","Estimates a sound-speed map by fitting full simulated waveforms to measured data.",14),
("DORT","decomposition of the time-reversal operator","Eigen-analysis of the inter-element response matrix; for well-resolved point scatterers, each strong singular vector focuses on one scatterer.",6),
("SINR","signal-to-interference-plus-noise ratio","Signal power divided by interference plus noise power; the figure of merit for adaptive beamformers.",7),
("RMB","Reed–Mallett–Brennan rule","Result that a sample covariance from about 2N snapshots costs roughly 3 dB of SINR in an N-element adaptive beamformer.",7),
("SMI","sample matrix inversion","Adaptive beamforming that inverts the measured sample covariance matrix.",7),
# --- beamforming, imaging ---
("DAS","delay-and-sum","Beamforming by delaying each channel to align echoes from a point, then summing; the reference method.",23),
("PSF","point spread function","Image of a single point scatterer; sets resolution and sidelobe levels.",23),
("FWHM","full width at half maximum","Width of a peak at half its maximum (−6 dB for amplitude); the usual resolution measure.",23),
("MV","minimum variance (Capon) beamformer","Adaptive beamformer that minimizes output power while keeping unit gain in the look direction.",25,[5,7,25,26]),
("MVDR","minimum variance distortionless response","Another name for the minimum-variance (Capon) beamformer.",7),
("ESBMV","eigenspace-based minimum variance","MV beamformer whose weights are projected onto the signal subspace of the covariance matrix.",25),
("CF","coherence factor","Ratio of coherent to incoherent energy across the aperture; used as a pixel weight that suppresses clutter.",25,[5,7,25,26,32,33]),
("GCF","generalized coherence factor","Coherence factor that counts low spatial frequencies across the aperture as coherent energy.",25),
("PCF","phase coherence factor","Weight based on the spread of channel phases instead of amplitudes.",25),
("SCF","sign coherence factor","Weight based on the agreement of channel signs (polarity).",25),
("SLSC","short-lag spatial coherence","Image formed from the spatial coherence of channel signals at small element lags, not from echo amplitude.",25),
("VCZ","van Cittert–Zernike (theorem)","For diffuse scatterers, the spatial coherence of echoes across the receive aperture is the Fourier transform of the insonified intensity distribution; at the transmit focus it equals the autocorrelation of the transmit apodization.",7),
("DMAS","delay-multiply-and-sum","Nonlinear beamformer that sums products of channel pairs after delay.",25),
("FXPF","f-x prediction filtering","Suppresses incoherent clutter by predicting each channel from its neighbours in the frequency–space domain.",25),
("ADMIRE","aperture domain model image reconstruction","Model-based beamformer that fits channel data with a set of modelled wavefronts and keeps only the components from the region of interest.",25),
("ROI","region of interest","Image region selected for measurement or processing.",26),
("CNR","contrast-to-noise ratio","Difference of mean intensities inside and outside a target, divided by a noise or speckle measure.",26),
("CR","contrast ratio","Ratio of mean intensities inside and outside a target, usually in dB.",26,[25,26]),
("gCNR","generalized contrast-to-noise ratio","1 minus the overlap of the intensity distributions inside and outside a target; ranges from 0 to 1 and is unchanged by monotonic transforms such as log compression (Rodriguez-Molares et al. 2020).",26),
("OVL","overlap (of histograms)","Area shared by the inside and outside intensity distributions; gCNR = 1 − OVL.",26),
("PICMUS","Plane-wave Imaging Challenge in Medical Ultrasound","IUS 2016 challenge that released shared plane-wave datasets and metrics for comparing beamformers.",25),
("DOF","depth of field","Axial range over which a focused beam stays near its focal width.",23),
("PWI","plane-wave imaging","Imaging with unfocused plane-wave transmits, often at several angles that are compounded.",24),
("SAFT","synthetic aperture focusing technique","Imaging that focuses every pixel by combining many single-element or small-aperture transmits.",24),
("RCA","row–column addressed array","2D array whose elements are addressed through whole rows or whole columns (e.g. rows on transmit, columns on receive), so N+N channels serve an N×N aperture.",19),
("SoS","speed of sound","Propagation speed of sound in the medium; about 1540 m/s is the usual soft-tissue assumption.",32),
("CUTE","computed ultrasound tomography in echo mode","Estimates a sound-speed map from phase shifts between images beamformed at different transmit/receive angles.",32),
("CMA","common mid-angle","CUTE refinement (Stähli et al. 2020) that compares transmit/receive angle pairs sharing the same mid-angle; these sample the same k-space region, so their speckle stays correlated and the phase difference reflects sound-speed error.",32),
("REFoCUS","retrospective encoding for conventional ultrasound sequences","Decodes the transmit sequence from channel data so any transmit set can be refocused like synthetic aperture data.",24),
("ULM","ultrasound localization microscopy","Super-resolution imaging that localizes and tracks individual microbubbles over many frames.",31),
("PALA","Performance benchmarking of microbubble-localization algorithms","Open ULM benchmark (Heiles et al. 2022) with shared data and metrics.",31),
("FRC","Fourier ring correlation","Resolution measure from the correlation of two independent half-images over rings in k-space.",31),
("NN","neural network","Learned model built from layers of weighted sums and nonlinearities.",31,[31]),
# --- Doppler, elastography, contrast ---
("CW","continuous wave","Transmission without pulses; gives Doppler without range resolution.",29),
("PW","pulsed wave","Doppler mode with pulsed transmission and a range gate.",29,[22,29]),
("PD","power Doppler","Image of the Doppler signal power after clutter filtering, regardless of velocity.",29,[6,29]),
("ARFI","acoustic radiation force impulse","Imaging of tissue displacement caused by a long focused push pulse.",30),
("SWE","shear wave elastography","Measures shear-wave speed to estimate tissue stiffness.",30),
("TOF","time of flight","Arrival-time method, e.g. estimating shear-wave speed from arrival times at several lateral positions.",30),
("CEUS","contrast-enhanced ultrasound","Imaging with gas microbubble contrast agents.",28),
("TIC","time–intensity curve","Echo intensity in an ROI versus time after contrast injection.",28),
("TTP","time to peak","Time from arrival (or injection) to the TIC maximum.",28),
("MTT","mean transit time","Mean time contrast takes to pass through the tissue; a perfusion parameter from the TIC.",28),
("CTR","contrast-to-tissue ratio","Microbubble signal relative to the residual tissue signal after contrast processing, in dB.",28),
("DSPC","distearoylphosphatidylcholine","A lipid commonly used in microbubble shells.",28),
# --- tissue characterization ---
("QUS","quantitative ultrasound","Estimates tissue properties (attenuation, backscatter, scatterer size, speed of sound) as numbers rather than images.",27),
("BSC","backscatter coefficient","Backscattered power per unit volume, solid angle and incident intensity; frequency dependence carries scatterer size.",27),
("ESD","effective scatterer diameter","Scatterer size estimated by fitting a form factor to the frequency dependence of the BSC.",27),
("SLD","spectral log difference","Attenuation estimate from the log ratio of power spectra from two depths in a homogeneous region; its slope versus frequency, divided by 4Δz, gives the attenuation coefficient slope (Np/cm/MHz).",27),
# --- transducers, hardware ---
("PZT","lead zirconate titanate","The standard piezoelectric ceramic for medical transducers.",16),
("PMN-PT","lead magnesium niobate–lead titanate","Relaxor single crystal with higher coupling than PZT; used in wide-band probes.",16),
("PVDF","polyvinylidene fluoride","Flexible piezoelectric polymer with low impedance; common in hydrophones.",16),
("KLM","Krimholtz–Leedom–Matthaei model","Equivalent circuit of a thickness-mode transducer as an acoustic transmission line coupled to an electrical port.",16),
("BVD","Butterworth–Van Dyke model","Lumped equivalent circuit (static capacitance in parallel with a series RLC) of a resonator near resonance.",20),
("ABCD","ABCD (transmission) matrix","Two-port representation that chains layers by matrix multiplication.",16),
("MRayl","megarayl","Unit of acoustic impedance, 10⁶ kg/(m²·s). Soft tissue is about 1.5 MRayl, PZT about 34.",17),
("CMUT","capacitive micromachined ultrasonic transducer","Transducer made of thin vibrating membranes over vacuum gaps, built with silicon micromachining.",18),
("PMUT","piezoelectric micromachined ultrasonic transducer","Micromachined plate transducer driven by a thin piezoelectric film.",18),
("AlN","aluminium nitride","Thin-film piezoelectric used in PMUTs; CMOS-compatible.",18),
("ScAlN","scandium aluminium nitride","AlN alloyed with scandium for a larger piezoelectric coefficient.",18),
("FDTD","finite-difference time-domain","Numerical wave simulation on a grid, stepping fields forward in time.",21),
("FEM","finite element method","Numerical solution of field equations on a mesh of small elements.",17),
("FEA","finite element analysis","Simulation using the finite element method.",17),
("CFL","Courant–Friedrichs–Lewy condition","Stability limit on the time step of explicit wave solvers: c·Δt/Δx must stay below a constant.",21),
("PPW","points per wavelength","Grid samples per wavelength in a simulation; too few cause numerical dispersion.",21),
("SIR","spatial impulse response","Velocity potential at a field point produced by an impulsive normal velocity of the transducer face; the pressure is ρ₀ times the time derivative of the excitation convolved with it.",21),
("ASIC","application-specific integrated circuit","Custom chip, for example the in-probe electronics of a matrix array.",19),
("ADC","analog-to-digital converter","Converts the amplified analog echo into samples.",20),
("DAC","digital-to-analog converter","Converts digital values into an analog voltage.",20),
("LNA","low-noise amplifier","First receive amplifier; sets most of the system noise figure.",20),
("VGA","variable-gain amplifier","Amplifier whose gain changes with depth to apply TGC.",20),
("TGC","time-gain compensation","Gain that increases with echo time to offset attenuation.",20),
("NF","noise figure","Degradation of SNR through a stage, in dB.",20,[20]),
("ENOB","effective number of bits","Resolution an ADC actually delivers once noise and distortion are counted.",20),
("FPGA","field-programmable gate array","Reconfigurable chip used for beamforming and data handling.",20),
("HV","high voltage","Transmit supply voltage, typically tens of volts up to about ±100 V (some systems higher).",20),
("MOSFET","metal–oxide–semiconductor field-effect transistor","The switching transistor of pulsers and multiplexers.",20),
("CMOS","complementary metal–oxide–semiconductor","The standard integrated-circuit process; CMUTs and PMUTs can be built on top of it.",18),
("FD","finite difference","Approximating derivatives by differences on a grid.",21,[15,21]),
("PML","perfectly matched layer","Absorbing boundary layer that stops reflections at the edge of a simulation grid.",21),
("KZK","Khokhlov–Zabolotskaya–Kuznetsov equation","Parabolic model of nonlinear, diffracting, absorbing sound beams.",15),
("TEE","transesophageal echocardiography","Cardiac imaging with a probe placed in the oesophagus.",19),
("IVUS","intravascular ultrasound","Imaging from a catheter inside a blood vessel.",18),
# --- acoustic output, safety ---
("MI","mechanical index","Derated (0.3 dB/cm/MHz) peak rarefactional pressure in MPa divided by the square root of the acoustic working frequency in MHz; indicates the likelihood of inertial cavitation (FDA limit 1.9).",22,[10,20,21,22,23,28]),
("TI","thermal index","Ratio of the relevant (attenuated, bounded) acoustic power to the power that raises a model tissue by 1 °C; an exposure indicator, not a measured temperature rise.",22),
("TIS","soft-tissue thermal index","TI for soft tissue only.",22),
("TIB","bone thermal index","TI with bone at or near the focus.",22),
("PII","pulse intensity integral","Time integral of instantaneous intensity over one pulse.",22),
("ISPTA","spatial-peak temporal-average intensity","Highest temporal-average intensity in the field; its derated value ISPTA.3 is limited by FDA to 720 mW/cm² for most applications, alongside MI ≤ 1.9.",22),
("SPTA","spatial-peak temporal-average","Short for spatial-peak temporal-average intensity (ISPTA).",22),
("ALARA","as low as reasonably achievable","Safety principle: use the lowest output and shortest exposure that answer the clinical question.",22),
("CEM43","cumulative equivalent minutes at 43 °C","Thermal dose: heating converted to the equivalent time at 43 °C.",22),
("IEC","International Electrotechnical Commission","Standards body whose standards define acoustic output measurement and safety for ultrasound.",22),
("FDA","US Food and Drug Administration","US regulator for medical devices, including ultrasound output limits.",22),
("AIUM","American Institute of Ultrasound in Medicine","Professional society that issues safety and practice statements.",22),
("DR","dynamic range","Ratio, in dB, between the largest and smallest levels a system or display represents; in B-mode, the span of log-compressed values mapped from white to black.",26,[6,8,25,26]),
("FT","Fourier transform","Decomposition of a signal into complex exponentials; the continuous counterpart of the DFT.",4),
("ODE","ordinary differential equation","An equation relating a function of one variable to its derivatives.",1),
("ACF","autocorrelation function","Correlation of a signal with a shifted copy of itself, as a function of the shift.",26),
("AIC","Akaike information criterion","Model-order selection rule that trades goodness of fit against the number of parameters; used here to choose the AR order.",27),
("RANSAC","random sample consensus","Robust fitting: models are fitted to random minimal subsets and the one with the most inliers is kept.",30),
("KVFD","Kelvin–Voigt fractional derivative model","Viscoelastic model that adds a spring in parallel with a fractional-order element (spring-pot).",30),
("PSTD","pseudo-spectral time domain","Wave solver that computes spatial derivatives with FFTs, so it needs only a few grid points per wavelength (k-Wave uses a k-space PSTD method).",21),
("USCT","ultrasound computed tomography","Tomographic imaging with transducers surrounding the object (for example the breast), reconstructing sound speed and attenuation as well as reflectivity.",14),
("THI","tissue harmonic imaging","Imaging with the second harmonic generated by nonlinear propagation in tissue, which reduces clutter from near-field reverberation and sidelobes.",15),
("HIFU","high-intensity focused ultrasound","Therapeutic focused ultrasound that heats and ablates tissue at the focus.",15),
("MRE","magnetic resonance elastography","MRI method that images shear waves from an external vibrator to map tissue stiffness.",30),
("SSI","supersonic shear imaging","Shear wave elastography method that moves the push focus faster than the shear wave speed, creating a Mach cone of shear waves.",30),
("QIBA","Quantitative Imaging Biomarkers Alliance","RSNA initiative that publishes profiles for standardizing quantitative imaging measurements, including shear wave speed.",30),
("TTE","transthoracic echocardiography","Cardiac ultrasound imaging through the chest wall.",19),
("MEMS","micro-electro-mechanical systems","Microscale mechanical structures made with semiconductor fabrication; CMUTs and PMUTs are MEMS devices.",18),
("PDMS","polydimethylsiloxane","Silicone rubber used for lenses and coatings; low sound speed and fairly high attenuation.",17),
("RTV","room-temperature-vulcanizing (silicone)","Silicone rubber cured at room temperature; the usual acoustic lens material (sound speed about 1000 m/s).",17),
("CRB","Cramér–Rao bound","Another name for the Cramér–Rao lower bound (CRLB).",12),
("GPU","graphics processing unit","Massively parallel processor used for beamforming, FFTs and simulation.",25),
("EFSUMB","European Federation of Societies for Ultrasound in Medicine and Biology","European professional federation that publishes clinical and safety guidelines.",22),
("CLASS","closed-loop accumulation of single scattering","Aberration-correction method from optical microscopy that iteratively estimates input and output phase corrections from the reflection matrix.",33),
]
import json
out=[]
for e in G:
    t,f,d,m=e[:4]; only=e[4] if len(e)>4 else None
    r={'t':t,'f':f,'d':d,'m':m}
    if only: r['only']=only
    out.append(r)
assert len({r['t'] for r in out})==len(out)
json.dump(out,open('glossary.json','w',encoding='utf-8'),indent=1,ensure_ascii=False)
print(len(out),'terms')
